def knn_vote(train: list[list[float]], labels: list[int], query: list[float], k: int) -> int:
    n: int = len(train)
    dists: list[float] = []
    for r in range(n):
        dists.append(sum((train[r][c] - query[c]) * (train[r][c] - query[c]) for c in range(len(query))))
    taken: list[bool] = []
    for r in range(n):
        taken.append(False)
    votes: dict[int, int] = {}
    order: list[int] = []
    for t in range(k):
        best: int = -1
        for r in range(n):
            if not taken[r]:
                if best == -1 or dists[r] < dists[best]:
                    best = r
        if best == -1:
            break
        taken[best] = True
        order.append(best)
        votes[labels[best]] = votes.get(labels[best], 0) + 1
    winner: int = -1
    top: int = 0
    for idx in order:
        c2: int = votes.get(labels[idx], 0)
        if c2 > top:
            top = c2
            winner = labels[idx]
    return winner
